import * as T from './vendor/three.module.js';import{GLTFLoader}from'./vendor/GLTFLoader.js';import{OrbitControls}from'./vendor/OrbitControls.js';
const canvas=document.getElementById('stage'),status=document.getElementById('status'),badge=document.getElementById('badge');let renderer,mixer,current,actions={},clock=new T.Clock(),model,back=false;
function fallback(error){console.warn(error);canvas.style.display='none';document.getElementById('fallback').style.display='block';badge.textContent='Still render · WebGL unavailable';status.textContent='This browser cannot show live 3D. These are actual model renders; they are not animated.';document.querySelectorAll('button').forEach(b=>b.disabled=true);}
try{renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance',precision:'highp'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2.0));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;const scene=new T.Scene();scene.background=new T.Color('#a9bcc3');scene.add(new T.HemisphereLight(0xffffff,0x506674,2.5));const key=new T.DirectionalLight(0xffeddd,3);key.position.set(2,4,3);scene.add(key);const rim=new T.DirectionalLight(0xb0eaff,2);rim.position.set(-2,2,-2);scene.add(rim);const camera=new T.PerspectiveCamera(34,1,.01,50);camera.position.set(2.8,1.8,3.8);const controls=new OrbitControls(camera,canvas);controls.target.set(0,.95,0);controls.enableDamping=true;controls.minDistance=2;controls.maxDistance=6;controls.maxPolarAngle=Math.PI*.52;controls.update();const floor=new T.Mesh(new T.CircleGeometry(3,64),new T.MeshStandardMaterial({color:0x93aab1,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.005;scene.add(floor);function resize(){const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas.parentElement);resize();function select(name){if(!actions[name])return;const next=actions[name];if(current===next)return;next.reset().play();if(current)current.crossFadeTo(next,.18,false);current=next;document.querySelectorAll('[data-clip]').forEach(b=>b.classList.toggle('active',b.dataset.clip===name));badge.textContent=name+' · Skeletal animation';}new GLTFLoader().load('./assets/runverse-male.glb',g=>{model=g.scene;scene.add(model);mixer=new T.AnimationMixer(model);g.animations.forEach(c=>actions[c.name]=mixer.clipAction(c));select('Idle');status.textContent='Drag to rotate. Pinch to zoom. Choose a motion to inspect the connected rig.';},undefined,fallback);document.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>select(b.dataset.clip));document.getElementById('turn').onclick=()=>{back=!back;camera.position.set(back?-2.8:2.8,1.8,back?-3.8:3.8);controls.update();};function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(mixer&&!document.hidden)mixer.update(dt);controls.update();renderer.render(scene,camera);}frame();}catch(e){fallback(e);}
